import json, random, subprocess, sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import ref

PROG = "/app/submission/scheduler.py"

def rand_borders(rng, U, maxR=5):
    R = rng.randint(1, maxR)
    if R == 1:
        return [0, U]
    cuts = sorted(rng.sample(range(1, U), R - 1)) if U > R else list(range(1, R))
    return [0] + cuts + [U]

def gen_stream(rng):
    Q = rng.randint(1, 6)
    L = rng.randint(1, 4)
    U = rng.choice([1, 2, 4, 8, 16, 32, 64])
    borders = rand_borders(rng, U)
    C = rng.randint(1, 5)
    E = rng.choice([0, 1, 2, 3, 5, 7])
    nsteps = rng.randint(0, 15)
    steps = []
    t = rng.randint(0, 3)
    counter = 0
    for i in range(nsteps):
        t += rng.randint(0, 5)
        lanes = rng.sample(range(L), rng.randint(0, L))
        arr = []
        for lane in lanes:
            counter += 1
            arr.append({"id": "p%d" % counter, "lane": lane, "rank": rng.randrange(U)})
        rng.shuffle(arr)
        steps.append({"t": t, "serve": rng.random() < 0.7, "arrivals": arr})
    return {"mode": "stream", "banks": Q, "lanes": L, "limit": U, "borders": borders,
            "capacity": C, "epoch": E, "steps": steps}

def gen_burst(rng):
    Q = rng.randint(1, 6)
    L = rng.randint(1, 4)
    U = rng.choice([1, 2, 4, 8, 16, 32, 64])
    borders = rand_borders(rng, U)
    n = rng.randint(0, 60)
    packets = []
    for i in range(n):
        packets.append({"id": "q%d" % i, "lane": rng.randrange(L), "rank": rng.randrange(U)})
    return {"mode": "burst", "banks": Q, "lanes": L, "limit": U, "borders": borders,
            "start_bank": rng.randrange(Q), "packets": packets}

def run(obj):
    proc = subprocess.run([sys.executable, "-I", "-B", PROG],
                          input=json.dumps(obj).encode(), stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE)
    if proc.returncode != 0:
        raise AssertionError("exit %d stderr=%s" % (proc.returncode, proc.stderr[:2000]))
    return json.loads(proc.stdout)

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    bad = 0
    for i in range(n):
        obj = gen_stream(rng) if rng.random() < 0.5 else gen_burst(rng)
        got = run(obj)
        exp = ref.ref_burst(obj) if obj["mode"] == "burst" else ref.ref_stream(obj)
        if got != exp:
            bad += 1
            print("MISMATCH", obj["mode"])
            print(json.dumps(obj))
            for key in exp:
                if got.get(key) != exp[key]:
                    if key == "events" or key == "departures":
                        for k2, (g, e) in enumerate(zip(got.get(key, []), exp[key])):
                            if g != e:
                                print("  first differing item", key, k2)
                                print("   got", json.dumps(g))
                                print("   exp", json.dumps(e))
                                break
                        else:
                            print("  length differs", len(got.get(key, [])), len(exp[key]))
                    else:
                        print("  key", key, "got", json.dumps(got.get(key)), "exp", json.dumps(exp[key]))
            if bad >= 3:
                break
    print("done, mismatches:", bad)

main()
